Решение. 
Создадим массив из 10 000 строк, каждая из которых будет представлять из себя 10 000 идущих подряд нулей. Индекс массива будет являться номером ряда, а индекс позиции символа в строке будет являться номером позиции в ряду. Считаем данные из файла, присваивая в соответствующей строке соответствующему символу единицу вместо нуля. Далее с помощью строкового метода string.ToWords разобьём каждую строку в массиве с разделителем «0», таким образом получим все последовательности из светлых точек в каждом ряду. Далее последовательно пройдём по каждой найденной последовательности светлых точек и найдём последовательность с наибольшей длиной.
Приведём решение на языке Pascal.
var 
 i, j, n, x, y, maxlen, maxnum: integer;
 screen: array[1..10000] of string;
 screen_str: array of string;
 f: text;
begin
 assign(f,'C:\26.txt');
 reset(f);
 readln(f, n);
 maxlen := 0;
 for i := 1 to 10000 do screen[i] := '0' * 10000;
 for i := 1 to n do begin
 readln(f, x, y);
 screen[x][y] := '1';
 end;
 for i := 1 to 10000 do begin
 screen_str := screen[i].ToWords('0');
 for j := 1 to screen_str.Length - 1 do
 if screen_str[j].Length > maxlen then begin
 maxlen := screen_str[j].Length;
 maxnum := i;
 end;
 end;
 writeln(maxlen, ' ', maxnum);
end.
